            shortExampleText: `${shortExampleText}…`,
            colors: [
                { label: 'Muted', className: 'fg-2' },
                { label: 'Primary', className: 'fg-primary' },
                { label: 'Info', className: 'fg-info' },
                { label: 'Success', className: 'fg-success' },
                { label: 'Warning', className: 'fg-warning' },
                { label: 'Danger', className: 'fg-danger' },
